function esc(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function icon(type,text){let id='ico'+(++iconSeq);const svg={claude:`<rect x="2" y="2" width="44" height="44" rx="11" fill="#c98464"/><g stroke="#fff6e8" stroke-width="2.6" stroke-linecap="round">${Array.from({length:12},(_,i)=>{let a=i*Math.PI/6;return `<path d="M${24+Math.cos(a)*5} ${24+Math.sin(a)*5}L${24+Math.cos(a)*15} ${24+Math.sin(a)*15}"/>`}).join('')}</g>`,browser:`<defs><linearGradient id="${id}" x2="1" y2="1"><stop stop-color="#0b8bed"/><stop offset=".5" stop-color="#12bdce"/><stop offset="1" stop-color="#49dfb5"/></linearGradient></defs><path d="M43 28c0 11-8 18-19 18C10 46 2 37 2 25 2 14 11 4 23 3c11 0 21 7 21 19 0 8-6 12-13 12-7 0-12-3-12-8 0-5 4-8 10-7-5-6-13-5-17 1-5 9 2 18 11 19 9 1 16-4 20-11" fill="url(#${id})"/><path d="M42 29c-5 4-17 3-22-1-4-4-2-9 3-11-11 0-17 8-12 17 5 10 23 10 31-5" fill="#0879c5"/>`,mail:`<defs><linearGradient id="${id}" x2=".8" y2="1"><stop stop-color="#48baff"/><stop offset="1" stop-color="#0867c5"/></linearGradient></defs><rect x="12" y="4" width="30" height="35" rx="3" fill="url(#${id})"/><path d="M8 17h36v25H8z" fill="#1488dd"/><path d="M8 18l18 13 18-13v24H8" fill="#2aa3ee"/><path d="M8 42l18-13 18 13" fill="#137bc4"/><rect x="2" y="11" width="22" height="27" rx="3" fill="#0a65b7"/><text x="13" y="30" text-anchor="middle" font-size="19" font-family="Segoe UI,sans-serif" fill="white">O</text>`,folder:`<defs><linearGradient id="${id}" x2="0" y2="1"><stop stop-color="#ffe18a"/><stop offset="1" stop-color="#f1b747"/></linearGradient></defs><path d="M3 10a4 4 0 014-4h12l5 6h17a4 4 0 014 4v23H3" fill="#dc9d32"/><path d="M5 15h37v20H5z" fill="#fff2ce"/><rect x="3" y="18" width="42" height="25" rx="4" fill="url(#${id})"/><path d="M5 19h38" stroke="#fff0b6" stroke-width="1.6"/>`,notepad:`<defs><linearGradient id="${id}" x2="1" y2="1"><stop stop-color="#c5ecff"/><stop offset="1" stop-color="#63abdb"/></linearGradient></defs><path d="M9 5h30v39H9z" fill="#478bb6"/><rect x="5" y="4" width="33" height="37" rx="3" fill="url(#${id})"/><path d="M12 14h20M12 20h20M12 26h20M12 32h14" stroke="#e9f8ff" stroke-width="2"/><path d="M14 3v5m7-5v5m7-5v5" stroke="#538cac" stroke-width="2"/>`,settings:`<defs><linearGradient id="${id}" x2=".7" y2="1"><stop stop-color="#d9e2e8"/><stop offset="1" stop-color="#8394a3"/></linearGradient></defs><path d="M20 3h8l2 6 5 3 6-1 4 7-4 5v6l4 5-4 7-6-1-5 3-2 5h-8l-2-5-5-3-6 1-4-7 4-5v-6l-4-5 4-7 6 1 5-3z" transform="translate(0 -2)" fill="url(#${id})"/><circle cx="24" cy="23" r="10" fill="#42647e"/><circle cx="24" cy="23" r="6" fill="#bdd7e9"/>`,terminal:`<rect x="2" y="5" width="44" height="37" rx="5" fill="#15324b"/><rect x="3" y="6" width="42" height="7" rx="4" fill="#44596d"/><path d="M11 20l7 6-7 6M24 33h12" stroke="#d9eafa" fill="none" stroke-width="3" stroke-linecap="round"/>`};return `<span class="icon ${type}" aria-hidden="true"><svg viewBox="0 0 48 48" fill="none">${svg[type==='notepad'&&text==='>_'?'terminal':type]||svg.notepad}</svg></span>`}
function stamp(){return new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'})}
function activeChat(){return state.chats.find(c=>c.id===state.active)||state.chats[0]}
function log(t){state.logs.push(stamp()+'  '+t);state.logs=state.logs.slice(-80)}
function notify(app,title,text,action){clearTimeout(toastTimer);$('toastApp').textContent=app;$('toastTitle').textContent=title;$('toastText').textContent=text;$('toast').classList.remove('hidden');toastAction=action||null;toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),9000)}
function addMail(title,body,from){state.mail.unshift({title,body,from,time:stamp(),read:false});renderNotifications();mailIndex=0;persist();if(windows.has('mail'))renderApp('mail');notify('邮件',title,from,()=>openApp('mail'))}
function refreshOthers(){persist();for(const id of windows.keys())if(id!=='claude'&&id!=='notes')renderApp(id)}
function renderApp(id){const f={claude:()=>'<div class="standalone-claude">'+claudeHtml()+'</div>',browser:edgeHtml,mail:mailHtml,files:filesHtml,notes:notesHtml,settings:settingsHtml,terminal:terminalHtml}[id];const body=$('body-'+id);if(!body||!f)return;body.innerHTML=f();if(id==='claude')scrollChat()}
function renderBrowser(){if(windows.has('claude'))renderApp('claude')}
function scrollChat(){setTimeout(()=>{const c=$('chatScroll');if(c)c.scrollTop=c.scrollHeight},0)}
function edgeHtml(){return `<div class="browser-body"><div class="browser-chrome"><div class="browser-tabs"><div class="browser-tab tab-active"><b>新建标签页</b><span>×</span></div><span>＋</span></div><div class="address-row"><button class="chrome-btn" aria-label="后退">←</button><button class="chrome-btn" data-action="edgeHome" aria-label="刷新">⟳</button><div class="address"><span>⌕</span><input id="addressInput" aria-label="地址栏" placeholder="搜索或输入 Web 地址" spellcheck="false"></div><span>☆</span><span>⋯</span></div></div><div class="edge-home"><div class="edge-clock">${stamp()}</div><p>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'})}</p><form id="edgeSearch" class="edge-search"><span>⌕</span><input id="edgeQuery" placeholder="搜索 Web" aria-label="搜索 Web"><button aria-label="搜索">→</button></form><div class="edge-favorites"><button data-open="claude">${icon('claude')}<span>Claude</span></button><button data-open="mail">${icon('mail')}<span>Outlook</span></button><button data-open="files">${icon('folder')}<span>文档</span></button></div></div></div>`}
function claudeHtml(){if(!state.loggedIn)return `<div class="auth-page"><div class="auth-logo">Claude</div><h1>你的想法，<br>可以走得更远。</h1><p>登录以继续你的工作。</p><div class="auth-card"><button class="auth-google" data-action="login"><span class="google-g">G</span> 以 Player 身份继续</button><div class="auth-divider">或</div><label>邮箱地址<input value="player@desktop.local" readonly aria-label="邮箱地址"></label><button class="auth-email" data-action="login">通过邮箱继续</button><div class="auth-note">继续即表示你已阅读服务条款和隐私政策。</div></div></div>`;
return `<div class="web realistic-web"><aside class="claude-sidebar"><div class="claude-word"><span>Claude</span> <button class="collapse-side" data-action="sidebar" aria-label="显示隐藏侧栏">▣</button></div><button class="side-item new-chat" data-action="new">＋ &nbsp; 新建聊天</button><button class="side-item" data-open="files"><span class="side-glyph">▱</span> 项目</button><button class="side-item" data-action="showArtifacts"><span class="side-glyph">◇</span> Artifacts</button><div class="chat-section"><span>最近的聊天</span><span>⋯</span></div><div class="chat-history">${state.chats.map(c=>`<button class="side-item ${c.id===state.active?'selected':''}" data-chat="${c.id}">${esc(c.title)}</button>`).join('')}</div><div class="sidebar-spacer"></div>${state.plan==='Free'?'<button class="upgrade-link" data-action="plans">升级计划 ↗</button>':''}<div class="account-wrap"><button class="account-button" data-action="account"><span class="avatar">P</span><span>Player<small>${state.plan} 计划</small></span><span style="margin-left:auto">⌃</span></button>${accountMenu?`<div class="account-popup"><div>player@desktop.local</div><button data-action="plans">管理订阅</button><button data-action="export">导出聊天数据</button><button data-open="settings">设置</button><button data-action="logout">退出登录</button></div>`:''}</div></aside><section class="claude-main"><div class="chat-top"><button class="mobile-side" data-action="sidebar" aria-label="打开聊天列表">☰</button><span>${activeChat().messages.length?esc(activeChat().title):'新对话'} <span class="model-label">▾</span></span><div class="chat-top-actions"><button data-action="new" title="新建对话">＋</button><button data-action="export" title="保存聊天到文档">↓</button><button data-action="account" title="账号菜单">⋯</button></div></div>${state.restricted?restrictedHtml():chatHtml()}<div class="web-foot">Claude 可能会犯错。请核查重要信息。</div></section></div>`}
function chatHtml(){let c=activeChat();return `<div class="chat-scroll ${c.messages.length?'has-messages':'is-empty'}" id="chatScroll">${c.messages.length?`<div class="message-stack">${c.messages.map(m=>`<article class="chat-message ${m.role}">${m.role==='assistant'?'<span class="reply-star">✳</span>':''}<div class="message-content">${format(m.text)}${m.attachment?'<div class="attachment-chip">▤ '+esc(m.attachment)+'</div>':''}</div></article>`).join('')}${typing?'<article class="chat-message assistant"><span class="reply-star">✳</span><span class="typing-dots"><i></i><i></i><i></i></span></article>':''}</div>`:`<div class="greeting"><div class="greeting-kicker">YOUR PERSONAL WORKSPACE</div><div class="greeting-line"><span class="hello-star">✳</span><h1>${(new Date().getUTCHours()+8)%24<12?'早上好':'下午好'}，Player</h1></div><p>从一个问题开始，把想法慢慢展开。</p></div>`}</div><form class="composer" id="composer"><div id="attachArea">${attached?'<div class="attachment-chip">▤ '+esc(attached)+' <button type="button" data-action="detach">×</button></div>':''}</div><textarea id="prompt" placeholder="你想聊些什么？" aria-label="发送消息给 Claude" rows="2" ${typing?'disabled':''}>${esc(c.draft||'')}</textarea><div class="composer-bottom"><div><button type="button" class="attach-button" data-action="attach" title="添加文件">＋</button><button type="button" class="tool-button" data-action="tools">⚑ 工具</button></div><div class="composer-right"><button type="button" class="model-button" data-action="model">${esc(ChatEngine.status().label)} ▾</button>${typing?'<button type="button" class="send" data-action="cancelGeneration" aria-label="停止生成">■</button>':'<button type="submit" class="send" aria-label="发送消息">↑</button>'}</div></div></form>${c.messages.length?'':`<div class="suggestions"><button data-suggest="帮我写一段 Python 代码">⌘ 编写代码</button><button data-suggest="帮我梳理一下项目计划">▱ 整理思路</button><button data-suggest="解释一下动能定理">◈ 学点新东西</button></div>`}`}
function format(s){return esc(s).replace(/```([\s\S]*?)```/g,'<pre>$1</pre>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}
function generateReply(text){const t=text.toLowerCase();if(/你好|hi\b|hello|在吗/.test(t))return '你好！很高兴见到你。\n\n可以把你正在处理的问题发给我，我们一起梳理。你想从哪里开始？';if(/python|代码|编程/.test(t))return '当然。可以先从一个简单、可独立运行的例子开始：\n\n```python\ndef summarize(values):\n    if not values:\n        return {"count": 0, "mean": None}\n    return {"count": len(values), "mean": sum(values) / len(values)}\n\nprint(summarize([1, 2, 3, 4]))\n```\n\n这个函数统计数量并计算平均值。下一步可以添加输入校验和文件保存。你希望它用来处理哪一类数据？';if(/动能|物理|功|运动/.test(t))return '可以用“做功与速度变化”的关系来理解。\n\n**动能**是物体由于运动而具有的能量：Ek = ½mv²。\n\n**动能定理**说明：合外力对物体做的功，等于物体动能的变化。\nW合 = ½mv₂² − ½mv₁²。\n\n例如质量 2 kg 的物体从静止加速到 3 m/s，动能增加 9 J，合外力就做了 9 J 的功。\n\n你是在分析一整段运动，还是其中某个阶段？';if(/谢谢|感谢/.test(t))return '不客气！如果这部分内容有用，可以先保存一份，再继续下一步。';if(/封号|停用|风险|ip|网络/.test(t))return '如果看到异常提示，先区分网络故障、会话过期、额度限制和账号停用。\n\n社区经历能提供线索，但无法直接证明平台内部的判定原因。请保留具体提示，通过官方渠道核实。\n\n你可以在账号设置中查看连接权限。遇到具体问题时，应保留完整通知并核实账号状态。';if(/项目|计划|文档|大纲/.test(t)||attached)return '可以，我们先整理成一个可执行的工作计划。\n\n**1. 明确目标**\n写下一句话：项目要帮助谁完成什么事情。\n\n**2. 做出最小可用版本**\n只保留最关键的一条操作流程，先让它完整运行。\n\n**3. 检查结果**\n使用具体例子验证输入与输出，再记录尚未解决的问题。\n\n**4. 保存成果**\n把文档、代码和必要资料保存在自己能访问的位置。\n\n你可以先告诉我：现在最影响进度的是哪一个环节？';if(/继续|然后|下一步/.test(t))return '接下来，可以把刚才的方案拆成三个部分：\n\n- 已知条件：整理已经确认的信息。\n- 需要解决的问题：每次只选择一个具体目标。\n- 验证方法：用一个例子检查结果是否符合预期。\n\n先完成一小步，再决定是否需要调整。你希望先细化哪一部分？';return `我理解了，你想讨论“${text.slice(0,75)}${text.length>75?'…':''}”。\n\n可以先从目标、条件和判断标准三个方面梳理：\n\n1. 你最后希望得到什么结果？\n2. 已经有哪些确定的信息或限制？\n3. 用什么例子能检验方案是否有效？\n\n把其中最关键的一点补充给我，我们可以接着往下拆解。`}
function submitMessage(text){text=String(text||'').trim();if(!text||typing||!state.loggedIn||state.restricted)return false;const c=activeChat();c.draft='';c.messages.push({role:'user',text:text.slice(0,4000),attachment:attached});if(c.title==='新对话')c.title=text.slice(0,17);typing=true;const epoch=sessionEpoch,id=++generationId,usedAttachment=attached;attached=false;state.sent++;inspectEnvironment();persist();renderBrowser();maybeComedy();
 const finishStory=()=>{if(epoch!==sessionEpoch||id!==generationId||state.restricted)return;const found=StoryContext.detect(text),scored=StoryContext.score(found,state.localeClues);state.localeClues.push(...scored.added);if(scored.points>0)securityEvent('地区使用情境线索',scored.points);if(state.connections.shared)securityEvent('共享会话出现了新的访问者',14);if(state.connections.extension)securityEvent('第三方应用正在连续访问会话',18);persist()};
 if(!ChatEngine.status().connected){setTimeout(()=>{if(epoch!==sessionEpoch||id!==generationId||state.restricted)return;c.messages.push({role:'assistant',text:generateReply(usedAttachment?'项目文件 '+text:text),origin:'offline'});typing=false;persist();renderBrowser();finishStory()},550);return true}
 const history=c.messages.map(m=>{if(m.role!=='user'||!m.attachment)return m;const file=state.files.find(f=>f.name===m.attachment);return {...m,text:m.text+(file?'\n\n[附件 '+file.name+']\n'+file.content:'')}});
 const reply={role:'assistant',text:'',origin:'api'};c.messages.push(reply);let lastDraw=0;
 ChatEngine.complete(history,chunk=>{if(epoch!==sessionEpoch||id!==generationId||state.restricted)return;reply.text=chunk;if(Date.now()-lastDraw>70){lastDraw=Date.now();renderBrowser()}}).then(answer=>{if(epoch!==sessionEpoch||id!==generationId||state.restricted)return;reply.text=answer;typing=false;persist();renderBrowser();finishStory()}).catch(error=>{if(epoch!==sessionEpoch||id!==generationId||state.restricted)return;reply.error=true;reply.text=(reply.text?reply.text+'\n\n':'')+'[服务连接提示] '+error.message;typing=false;persist();renderBrowser()});return true}

function newChat(){if(!state.loggedIn)return;const c={id:Date.now(),title:'新对话',messages:[]};state.chats.unshift(c);state.active=c.id;attached=false;accountMenu=false;persist();renderBrowser();setTimeout(()=>$('prompt')?.focus(),0)}
function restrictAccount(){if(state.restricted)return;cancelComedy();closeDialog();generationId++;ChatEngine.cancel();reviewPending=false;state.restricted=true;state.reviewSnapshot={events:state.activity.slice(),environment:JSON.parse(JSON.stringify(state.environment)),plan:state.plan,elapsed:Date.now()-state.started};typing=false;accountMenu=false;log('Account access disabled after security review.');persist();renderBrowser();addMail('Your account has been disabled','Hello,\n\nFollowing a review of recent activity, access to your account has been disabled. You will no longer be able to send messages or start new conversations with this account.\n\nIf you believe this action was taken in error, please submit an appeal from the account notice in the app. Our team will review your request and contact you at this email address.\n\nFor security reasons, we cannot provide further details about this review.\n\nAccount Support','Claude Account Support');refreshOthers()}
function restrictedHtml(){return `<div class="restricted-page authentic-disabled"><div class="disabled-mark">✳</div><div class="disabled-account">player@desktop.local</div><h1>Your account has been disabled</h1><div class="restriction-detail">Access to this account has been disabled following a review of recent activity.<br><br>If you believe this was a mistake, you can submit an appeal. Our team will review your request and contact you by email.</div><div class="restriction-actions"><button class="auth-email" data-action="appeal" ${state.appealed?'disabled':''}>${state.appealed?'Appeal submitted':'Submit an appeal'}</button><button class="disabled-link" data-open="mail">Check your email ↗</button></div><p class="disabled-caption">You are currently unable to send messages or start new conversations.</p><details class="local-recovery"><summary>此设备上的数据与恢复选项</summary><div class="btn-row"><button class="primary" data-action="newLocalAccount">用另一个账号继续</button><button class="neutral" data-action="export">保存本地聊天</button><button class="neutral" data-action="reviewReport">查看事件记录</button><button class="neutral" data-action="restart">重置此电脑并重新开始</button></div><p class="tiny">重置将清除此设备上的聊天、文档和设置。</p></details></div>`}
function mailHtml(){const mails=state.mail;mailIndex=Math.min(mailIndex,mails.length-1);let m=mails[mailIndex];return `<div class="mail-layout"><aside class="mail-nav"><h2>Outlook</h2><button class="primary" data-action="compose">＋ 新邮件</button><div class="current">▣ 收件箱 &nbsp; ${mails.filter(x=>!x.read).length}</div><div>☆ 已标记</div><button class="mail-nav-link" data-action="compose">▱ 草稿</button><button class="mail-nav-link" data-action="localOutbox">↗ 本地发件箱</button></aside><div class="mail-list"><h3>收件箱</h3>${mails.map((x,i)=>`<button class="mail-item ${mailIndex===i?'active':''} ${x.read?'':'unread'}" data-mail="${i}"><b>${esc(x.from)}</b>${esc(x.title)}<small>${esc(x.time)}</small></button>`).join('')}</div><article class="mail-reading"><h2>${esc(m?.title||'收件箱')}</h2><div class="mail-sender">${esc(m?.from)} &lt;notifications@account.local&gt;<br>收件人：player@desktop.local</div><div style="white-space:pre-line">${esc(m?.body)}</div>${m?.action==='shareOffer'?'<div class="btn-row"><button class="primary" data-action="shareOffer">查看授权范围</button></div>':''}${state.restricted?'<div class="btn-row"><button class="primary" data-open="claude">查看账号状态 →</button></div>':''}</article></div>`}
function saveExport(){if(!state.loggedIn){notify('Claude','请先登录账号','使用你的账号继续。');return}let text=state.chats.map(c=>'# '+c.title+'\n\n'+c.messages.map(m=>(m.role==='user'?'你：':'助手：')+m.text).join('\n\n')).join('\n\n---\n\n');let limited=false;if(limited)text='部分数据导出\n\n'+text.slice(0,Math.floor(text.length*.6));const file={name:'Claude 聊天导出 '+stamp().replace(':','-')+'.txt',content:text||'当前没有聊天内容。',time:stamp()};state.files.unshift(file);state.exported=true;persist();accountMenu=false;renderBrowser();refreshOthers();notify('文件资源管理器',limited?'部分数据已导出':'聊天已保存到文档',file.name,()=>openApp('files'))}
function filesHtml(){return `<div class="files-layout"><div class="file-toolbar"><button class="neutral" data-action="newFile">＋ 新建文档</button><span class="file-toolbar-label">文档</span><input id="fileSearch" class="file-search" placeholder="搜索此文件夹" aria-label="搜索本地文档"></div><div class="breadcrumbs">⌂ 此电脑 &nbsp; › &nbsp; 文档</div><div class="file-content"><aside class="file-sidebar"><div>⌂ 主页</div><div>▣ 桌面</div><div>↓ 下载</div><div style="background:#e6f1fc">▱ 文档</div><div>▧ 此电脑</div></aside><div class="file-main"><div class="file-table-head"><span>名称</span><span>修改时间</span></div>${state.files.map((f,i)=>`<div class="file-list-row" data-filename="${esc(f.name.toLowerCase())}"><button class="file-open" data-file="${i}">📄 &nbsp; ${esc(f.name)}</button><span>${esc(f.time)}</span><button class="text-link" data-preview="${i}">预览</button><button class="text-link" data-download="${i}">保存到本机</button></div>`).join('')}<div class="folder-status">${state.files.length} 个项目</div></div></div></div>`}

function notesHtml(){return `<div class="note-layout"><div class="note-menu"><button class="text-link" data-action="saveNote">文件 / 保存</button>　 编辑　 查看　 <span id="noteStatus"></span></div><textarea class="note-editor" id="noteEditor" aria-label="记事本文档" spellcheck="false">${esc(state.notes)}</textarea><div class="note-footer">纯文本　 UTF-8　 文本文档</div></div>`}
function settingsHtml(){return `<div class="settings-layout"><h2>设置</h2><div class="setting-row"><span class="setting-icon">◉</span><strong>Player<small>player@desktop.local</small></strong></div><div class="setting-row"><span class="setting-icon">⌁</span><strong>网络和 Internet<small>以太网 · 已连接</small></strong><select id="networkSelect" aria-label="网络连接">${['自动连接','工作网络','公共网络','香港出口','东京出口','洛杉矶出口','上海直连'].map(t=>`<option ${state.network===t?'selected':''}>${t}</option>`).join('')}</select></div>${environmentSettingsHtml()}<div class="setting-row"><span class="setting-icon">▧</span><strong>账号<small>${state.restricted?'已受限':'已登录'} · Claude ${state.plan}</small></strong><button class="neutral" data-action="plans">管理订阅</button></div><div class="setting-row"><span class="setting-icon">✧</span><strong>AI 服务<small>${ChatEngine.status().connected?esc(ChatEngine.status().name)+' · '+esc(ChatEngine.status().label):'离线模式 · 尚未配置真实模型'}</small></strong><button class="neutral" data-action="aiSettings">${ChatEngine.status().connected?'管理连接':'连接'}</button></div><h3 style="font-size:15px;font-weight:500;margin-top:26px">应用权限与连接</h3><div class="setting-row"><span class="setting-icon">♧</span><strong>Cloud Office 共享会话<small>${state.connections.shared?'已授权 · 其他成员可以访问当前会话':'未连接'}</small></strong>${state.connections.shared?'<button class="neutral" data-action="revokeShare">撤销授权</button>':'<span class="setting-val">无访问权限</span>'}</div><div class="setting-row"><span class="setting-icon">⚑</span><strong>Batch Assistant<small>${state.connections.extension?'已授权 · 可以批量发送请求并读取会话':'未安装'}</small></strong>${state.connections.extension?'<button class="neutral" data-action="revokeExtension">移除</button>':'<span class="setting-val">无访问权限</span>'}</div><div class="setting-row"><span class="setting-icon">☷</span><strong>系统信息<small>PLAYER-PC · Windows 11<br>设备状态正常</small></strong></div><div class="btn-row"><button class="neutral" data-action="restart">重置此电脑</button></div></div>`}
function terminalHtml(){return `<div class="terminal"><div class="dim">Windows PowerShell</div><br>${state.logs.map(s=>`<div>${esc(s)}</div>`).join('')}<br><form id="terminalForm"><label class="green">PS C:\\Users\\Player&gt; <input id="terminalInput" autocomplete="off" spellcheck="false" aria-label="终端命令" placeholder="help"></label></form><p class="dim">输入 help 查看可用命令。</p></div>`}
function showDialog(html){$('osDialog').innerHTML=html;$('osDialog').showModal()}
function closeDialog(){$('osDialog').close()}
function plans(){showDialog(`<div class="dialog-heading">选择适合你的计划<button data-action="closeDialog" aria-label="关闭">×</button></div><div class="plan-grid"><div><h3>Free</h3><p>从日常对话开始</p><b>¥0</b><button class="neutral" data-action="closeDialog">当前计划</button></div><div><h3>Pro</h3><p>为日常工作提供更多空间</p><b>¥120 <small>/ 月</small></b><button class="primary" data-plan="Pro">升级</button></div><div><h3>Max</h3><p>为高强度工作提供支持</p><b>¥600 <small>/ 月</small></b><button class="primary" data-plan="Max">升级</button></div></div><p class="tiny">账户余额 ¥${state.money}</p>`)}
function checkout(plan){const cost=plan==='Max'?600:120;showDialog(`<div class="dialog-heading">完成订阅<button data-action="closeDialog">×</button></div><h3>Claude ${esc(plan)}</h3><p>总计 ¥${cost}</p><label class="checkout-label">付款方式<input readonly value="账户余额 · ¥${state.money}"></label><button class="primary" data-pay="${plan}" ${state.money<cost?'disabled':''}>${state.money<cost?'余额不足':'确认订阅'}</button>`)}
function pay(plan){const cost=plan==='Max'?600:120;if(state.money<cost)return;state.money-=cost;state.plan=plan;log('Claude '+plan+' subscription activated.');persist();closeDialog();renderBrowser();refreshOthers();addMail('订阅确认：Claude '+plan,'你的订阅已开通。\n\n计划：Claude '+plan+'\n付款金额：¥'+cost+'\n\n感谢你的订阅。你可以在应用设置中管理计划。','Claude Billing')}
function appeal(){if(!state.restricted||state.appealed)return;showDialog(`<div class="dialog-heading">账号申诉<button data-action="closeDialog">×</button></div><p>请说明你的情况</p><textarea id="appealText" class="appeal-input" placeholder="描述你遇到的问题，以及希望我们核实的信息。"></textarea><button class="primary" data-action="sendAppeal">提交申诉</button>`)}
function sendAppeal(){if(state.appealed||!state.restricted)return;state.appealed=true;const epoch=sessionEpoch;closeDialog();renderBrowser();notify('账号支持','申诉已提交','我们会通过电子邮件告知结果。');setTimeout(()=>{if(epoch!==sessionEpoch)return;const ok=Math.random()<.4;if(ok){state.restricted=false;state.risk=0;state.warnings=0;state.connections={shared:false,extension:false};state.environment.sessions=state.environment.sessions.slice(0,1);state.environment.seen=[];state.environment.transitions=[]}log(ok?'Account access restored.':'Account restriction upheld.');persist();renderBrowser();refreshOthers();addMail(ok?'申诉结果：账号访问已恢复':'申诉结果：维持当前限制',ok?'我们已重新审核你的账号，并恢复访问。\n\n请检查已授权的应用和连接，妥善保管你的会话与账号信息。':'我们已审核你提交的申诉，目前维持该账号的访问限制。\n\n你仍可导出当前允许访问的数据。','Claude Support')},1300)}
function downloadFile(index){const f=state.files[index];if(!f)return;const url=URL.createObjectURL(new Blob([f.content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function readFile(i){const f=state.files[i];if(!f)return;recordActivity('打开本地文档：'+f.name);state.notes=f.content;persist();openApp('notes')}
function saveNote(){const el=$('noteEditor');if(!el)return;state.notes=el.value;const existing=state.files.find(f=>f.name==='我的笔记.txt');if(existing){existing.content=state.notes;existing.time=stamp()}else state.files.unshift({name:'我的笔记.txt',content:state.notes,time:stamp()});persist();if($('noteStatus'))$('noteStatus').textContent='已保存';recordActivity('保存了本地文档','repair');if(desktopReady)maybeComedy('files');if(windows.has('files'))renderApp('files')}
function resetGame(){if(!confirm('重置此电脑？这将清除当前聊天记录、文档和设置。'))return;sessionEpoch++;generationId++;cancelComedy();ChatEngine.disconnect();reviewPending=false;state=fresh();renderNotifications();typing=false;accountMenu=false;attached=false;mailIndex=0;persist();$('startMenu').classList.add('hidden');closeDialog();for(const id of windows.keys())renderApp(id);openApp('claude')}
function setup(){for(const [id,type,text,title] of appList){$('shortcuts').insertAdjacentHTML('beforeend',`<button class="shortcut" data-open="${id}">${icon(type,text)}<span>${title}</span></button>`);$('pinned').insertAdjacentHTML('beforeend',`<button data-open="${id}">${icon(type,text)}${title}</button>`);$('taskApps').insertAdjacentHTML('beforeend',`<button data-task="${id}" class="${['notes','settings','terminal'].includes(id)?'optional-task':''}" title="${title}" aria-label="${title}">${icon(type,text)}</button>`)}openApp('claude');persist()}
const actions={new:newChat,export:saveExport,plans,logout:()=>{state.loggedIn=false;generationId++;ChatEngine.cancel();typing=false;accountMenu=false;persist();renderBrowser()},login:()=>{state.loggedIn=true;persist();renderBrowser()},account:()=>{accountMenu=!accountMenu;if(window.innerWidth<650)$('win-claude')?.classList.add('show-sidebar');renderBrowser()},home:()=>{browserTab='claude';renderBrowser()},refresh:()=>{renderBrowser();notify('Claude','页面已刷新','页面已重新加载。')},sidebar:()=>{$('win-claude')?.classList.toggle('show-sidebar')},attach:()=>showDialog(`<div class="dialog-heading">选择项目文件<button data-action="closeDialog">×</button></div><p class="tiny">文档</p>${state.files.map((f,i)=>`<button class="attachment-option" data-attach="${i}">📄 ${esc(f.name)}</button>`).join('')}`),detach:()=>{attached=false;renderBrowser()},tools:()=>showDialog('<div class="dialog-heading">工具<button data-action="closeDialog">×</button></div><p>连接应用和工具，处理更多工作。</p><button class="attachment-option" data-action="pluginOffer">⚑ Batch Assistant — 批处理助手</button><button class="neutral" data-open="files">打开项目文件</button>'),model:openAISettings,closeDialog,appeal,sendAppeal,restart:resetGame,saveNote,newFile:()=>{state.notes='';openApp('notes')},compose:()=>showDialog('<div class="dialog-heading">新邮件<button data-action="closeDialog">×</button></div><p>收件人</p><input readonly value="尚未添加联系人" class="appeal-input" style="min-height:40px"><p class="tiny">请从联系人中选择收件人。</p>')};

// Fictional gameplay rules. These values do not model any provider's actual enforcement.
let reviewPending=false;
function queueReview(){if(reviewPending||state.restricted||state.risk<=0)return;reviewPending=true;const epoch=sessionEpoch;setTimeout(()=>{if(epoch!==sessionEpoch)return;reviewPending=false;if(state.risk<=0||state.restricted)return;const chance=Math.min(.92,state.risk/80);if(Math.random()<chance)restrictAccount()},5000+Math.floor(Math.random()*10000))}
function securityEvent(reason,points){if(state.restricted)return;recordActivity(reason,points>0?'signal':'context');state.risk=Math.min(100,state.risk+points);persist();queueReview()}

function revoke(kind){state.connections[kind]=false;if(kind==='shared')state.environment.sessions=state.environment.sessions.filter(x=>!x.shared);recordActivity('撤销 '+(kind==='shared'?'Cloud Office 共享授权':'Batch Assistant 权限'),'repair');state.risk=Math.max(0,state.risk-40);if(state.risk<35)state.warnings=0;log('Removed connection: '+kind);persist();renderBrowser();refreshOthers();notify('设置','已移除连接','该应用无法继续访问你的会话。')}
function shareOffer(){showDialog('<div class="dialog-heading">Cloud Office 请求访问<button data-action="closeDialog">×</button></div><p>此应用希望获得以下权限：</p><ul><li>读取你全部的聊天记录</li><li>使用当前登录会话发送消息</li><li>允许其他成员同时使用该会话</li></ul><p class="tiny">授权后，对方可以代表你的账号操作。请确认你信任此服务。</p><div class="btn-row"><button class="primary" data-action="grantShare">允许访问</button><button class="neutral" data-action="closeDialog">取消</button></div>')}
function pluginOffer(){showDialog('<div class="dialog-heading">安装 Batch Assistant<button data-action="closeDialog">×</button></div><p>提高效率，连续执行大量任务。</p><ul><li>读取全部聊天记录</li><li>保留账号访问会话</li><li>批量发送无人值守请求</li></ul><p class="tiny">来源：未知发布者</p><div class="btn-row"><button class="primary" data-action="grantExtension">安装并允许</button><button class="neutral" data-action="closeDialog">取消</button></div>')}
Object.assign(actions,{showArtifacts:()=>{openApp('files')},edgeHome:()=>renderApp('browser'),toggleNotifications:()=>{$('notificationCenter').classList.toggle('hidden')},shareOffer,pluginOffer,grantShare:()=>{closeDialog();state.connections.shared=true;state.environment.lastBackground=Date.now();securityEvent('共享会话已向外部成员开放',42);refreshOthers()},grantExtension:()=>{closeDialog();state.connections.extension=true;state.environment.lastBackground=Date.now();securityEvent('第三方应用获得会话与批量访问权限',44);refreshOthers()},revokeShare:()=>revoke('shared'),revokeExtension:()=>revoke('extension')});


function openAISettings(){const current=ChatEngine.status();showDialog(`<div class="dialog-heading">AI 服务连接<button data-action="closeDialog">×</button></div><p class="tiny">未连接模型时使用本地预设回复。连接真实 AI 需要自行填写接口与密钥。</p><div class="ai-config"><label>服务预设<select id="aiProvider"><option value="siliconflow" ${current.provider==='siliconflow'?'selected':''}>硅基流动</option><option value="openrouter" ${current.provider==='openrouter'?'selected':''}>OpenRouter</option><option value="custom" ${current.provider==='custom'?'selected':''}>自定义 · OpenAI 兼容接口</option></select></label><label>接口地址<input id="aiUrl" type="url" autocomplete="off" spellcheck="false" placeholder="https://api.example.com/v1" value="${esc(current.provider?current.url:'https://api.siliconflow.cn/v1/chat/completions')}"></label><label>模型 ID<input id="aiModel" autocomplete="off" spellcheck="false" placeholder="服务商提供的模型 ID" value="${esc(current.provider?current.model:'Qwen/Qwen2.5-7B-Instruct')}"></label><label>API Key<input id="aiKey" type="password" autocomplete="off" spellcheck="false" placeholder="个人密钥；无认证的自定义接口可留空"></label><label>最大输出 tokens<input id="aiMaxTokens" type="number" min="1" max="8192" value="${current.maxTokens||900}"></label><label>温度<input id="aiTemperature" type="number" min="0" max="2" step="0.1" value="${current.temperature??.7}"></label><label class="ai-consent"><input id="aiStream" type="checkbox" ${current.stream!==false?'checked':''}><span>流式显示回复（服务不支持时可关闭）</span></label><div class="ai-provider-note" id="aiProviderNote"></div><label class="ai-consent"><input id="aiConsent" type="checkbox"><span>我同意将当前对话与所选附件文字发送到此接口，并已核对模型价格。个人接口可能收费；密钥仅保留在本次页面内存中。</span></label><div class="ai-buttons"><button class="primary" data-action="connectAI">保存连接配置</button>${current.connected?'<button class="neutral" data-action="disconnectAI">断开个人连接</button>':''}</div><p id="aiConfigStatus" class="tiny" role="status"></p><p class="tiny">支持 /v1 基础地址或完整聊天接口。仅支持 HTTPS 的 OpenAI Chat Completions 协议。服务端须允许本网页的 CORS 跨域请求。首次发消息验证连接，刷新页面需重新填写个人密钥。</p></div>`);updateAIProviderNote(false)}
function updateAIProviderNote(reset=true){const provider=$('aiProvider')?.value,note=$('aiProviderNote');if(!note)return;const presets={siliconflow:['https://api.siliconflow.cn/v1/chat/completions','Qwen/Qwen2.5-7B-Instruct'],openrouter:['https://openrouter.ai/api/v1/chat/completions','openrouter/free'],custom:['','']};if(reset){$('aiUrl').value=presets[provider][0];$('aiModel').value=presets[provider][1];$('aiKey').value=''}note.textContent=provider==='custom'?'可连接自建网关、代理或其他 OpenAI 兼容服务。请仅填写你信任的地址，密钥会直接发送给该地址。':'接口和模型均可修改。是否免费以服务商控制台为准，不会自动更换模型。'}
function connectAI(){const status=$('aiConfigStatus');try{ChatEngine.connect($('aiProvider').value,$('aiKey').value,$('aiConsent').checked,{url:$('aiUrl').value,model:$('aiModel').value,maxTokens:$('aiMaxTokens').value,temperature:$('aiTemperature').value,stream:$('aiStream').checked});$('aiKey').value='';closeDialog();renderBrowser();if(windows.has('settings'))renderApp('settings');notify('AI 服务','连接配置已保存','发送消息以验证真实模型连接。')}catch(error){if(status)status.textContent=error.message}}
function cancelGeneration(){generationId++;ChatEngine.cancel();typing=false;persist();renderBrowser()}
Object.assign(actions,{aiSettings:openAISettings,connectAI,disconnectAI:()=>{generationId++;ChatEngine.disconnect();typing=false;closeDialog();renderBrowser();if(windows.has('settings'))renderApp('settings')},cancelGeneration});
document.addEventListener('change',event=>{if(event.target.id==='aiProvider')updateAIProviderNote()});

document.addEventListener('click',e=>{let b=e.target.closest('[data-open]');if(b){if($('osDialog').open)closeDialog();openApp(b.dataset.open);return}b=e.target.closest('[data-task]');if(b){const w=windows.get(b.dataset.task);if(w&&!w.classList.contains('hidden')&&b.classList.contains('active')){w.classList.add('hidden');updateTasks()}else openApp(b.dataset.task);return}b=e.target.closest('[data-tab]');if(b){browserTab=b.dataset.tab;renderBrowser();return}b=e.target.closest('[data-chat]');if(b){state.active=Number(b.dataset.chat);persist();renderBrowser();return}b=e.target.closest('[data-mail]');if(b){mailIndex=Number(b.dataset.mail);state.mail[mailIndex].read=true;renderNotifications();persist();renderApp('mail');return}b=e.target.closest('[data-plan]');if(b){checkout(b.dataset.plan);return}b=e.target.closest('[data-pay]');if(b){pay(b.dataset.pay);return}b=e.target.closest('[data-suggest]');if(b){const el=$('prompt');if(el){el.value=b.dataset.suggest;el.focus()}return}b=e.target.closest('[data-file]');if(b){closeDialog();readFile(Number(b.dataset.file));return}b=e.target.closest('[data-download]');if(b){downloadFile(Number(b.dataset.download));return}b=e.target.closest('[data-attach]');if(b){attached=state.files[Number(b.dataset.attach)]?.name||'项目草稿.txt';closeDialog();renderBrowser();return}b=e.target.closest('[data-action]');if(b)actions[b.dataset.action]?.()});
document.addEventListener('submit',e=>{if(e.target.id==='edgeSearch'){e.preventDefault();navigateEdge($('edgeQuery')?.value)}if(e.target.id==='composer'){e.preventDefault();submitMessage($('prompt')?.value)}if(e.target.id==='terminalForm'){e.preventDefault();const cmd=$('terminalInput').value.trim().toLowerCase();if(cmd==='batch'){securityEvent('检测到未授权的批量请求',48);log('Batch queue: 64 requests.')}else if(cmd==='help')log('可用命令：status / export / clear / batch');else if(cmd==='status')log('account: '+(state.restricted?'restricted':'active')+' | messages: '+state.sent+' | plan: '+state.plan);else if(cmd==='export')saveExport();else if(cmd==='clear')state.logs=[];else log('未识别的命令；输入 help。');persist();renderApp('terminal')}});
document.addEventListener('keydown',e=>{if(e.target.id==='prompt'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submitMessage(e.target.value)}if(e.target.id==='addressInput'&&e.key==='Enter'){e.preventDefault();navigateEdge(e.target.value)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&e.target.id==='noteEditor'){e.preventDefault();saveNote()}if(e.key==='Escape'){$('startMenu').classList.add('hidden');$('toast').classList.add('hidden')}});
document.addEventListener('input',e=>{if(e.target.id==='prompt'){activeChat().draft=e.target.value;persist()}if(e.target.id==='noteEditor'){state.notes=e.target.value;persist();if($('noteStatus'))$('noteStatus').textContent='未保存'}});document.addEventListener('change',e=>{if(e.target.id==='networkSelect')changeVirtualNetwork(e.target.value)});
$('startButton').onclick=()=>$('startMenu').classList.toggle('hidden');$('restart').onclick=resetGame;$('toastClose').onclick=e=>{e.stopPropagation();$('toast').classList.add('hidden')};$('toast').onclick=()=>{const f=toastAction;$('toast').classList.add('hidden');f?.()};window.addEventListener('resize',()=>{for(const w of windows.values()){if(w.classList.contains('maximized'))continue;if(w.offsetLeft>window.innerWidth-100)w.style.left='15px';if(w.offsetTop>window.innerHeight-100)w.style.top='15px'}});function tick(){$('clock').innerHTML=stamp()+'<br>'+new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}setup();tick();setInterval(tick,30000);queueReview();

function navigateEdge(value){if(/claude/i.test(value)){openApp('claude');return}if(/outlook|mail|邮箱/i.test(value)){openApp('mail');return}const home=document.querySelector('.edge-home');if(home)home.innerHTML='<div class="edge-offline"><h2>无法访问此页面</h2><p>请检查地址和网络连接，然后重试。</p><small>'+esc(String(value||''))+'</small><br><button class="primary" data-action="edgeHome">重新加载</button></div>'}
function renderNotifications(){const box=$('ncMessages');if(!box)return;const unread=state.mail.filter(m=>!m.read);box.innerHTML=unread.length?unread.slice(0,3).map(m=>'<button data-open="mail"><b>'+esc(m.from)+'</b><br>'+esc(m.title)+'</button>').join(''):'没有新通知';const now=new Date(Date.now()+8*3600000),year=now.getUTCFullYear(),month=now.getUTCMonth(),day=now.getUTCDate(),first=new Date(Date.UTC(year,month,1)).getUTCDay(),count=new Date(Date.UTC(year,month+1,0)).getUTCDate();$('ncCalendar').innerHTML='<h3>'+year+' 年 '+(month+1)+' 月</h3><div class="calendar-grid">'+['日','一','二','三','四','五','六'].map(d=>'<span class="day-name">'+d+'</span>').join('')+Array.from({length:first},()=>'<span></span>').join('')+Array.from({length:count},(_,i)=>'<span class="'+(i+1===day?'today':'')+'">'+(i+1)+'</span>').join('')+'</div>'}
$('taskSearch').onclick=()=>{$('startMenu').classList.toggle('hidden');if(!$('startMenu').classList.contains('hidden'))$('startSearchInput').focus()};document.addEventListener('input',e=>{if(e.target.id==='startSearchInput'){const value=e.target.value.trim().toLowerCase();$('pinned').querySelectorAll('button').forEach(b=>b.style.display=b.textContent.toLowerCase().includes(value)?'':'none')}});document.addEventListener('click',e=>{if(e.target.id==='desktop'){$('startMenu').classList.add('hidden');$('notificationCenter').classList.add('hidden')}});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('notificationCenter').classList.add('hidden')});renderNotifications();




// Only virtual machine state is used. No fingerprinting, real location or OS access.
function freshEnvironment(){return {language:'简体中文',region:'中国大陆',timezone:'UTC+08:00',shareDiagnostics:false,transitions:[],seen:[],sessions:[{device:'PLAYER-PC',place:'当前工作网络',shared:false}],lastBackground:Date.now()}}
function recordActivity(text,kind='context'){state.activity.push({text,kind,time:stamp(),at:Date.now()});state.activity=state.activity.slice(-100)}
function environmentSettingsHtml(){const env=state.environment;const select=(id,values,current)=>`<select id="${id}" aria-label="${id==='virtualRegion'?'国家或地区':id==='virtualLanguage'?'显示语言':'时区'}">${values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}</select>`;return `<h3 class="settings-section">时间和语言</h3><div class="setting-row"><span class="setting-icon">◎</span><strong>Windows 显示语言<small>应用使用此语言显示菜单与文本</small></strong>${select('virtualLanguage',['简体中文','English (United States)','日本語'],env.language)}</div><div class="setting-row"><span class="setting-icon">◷</span><strong>日期和时间<small>自动设置时区已关闭</small></strong>${select('virtualTimezone',['UTC+08:00','UTC+09:00','UTC−08:00'],env.timezone)}</div><div class="setting-row"><span class="setting-icon">⌖</span><strong>国家或地区<small>用于本地内容与格式</small></strong>${select('virtualRegion',['中国大陆','中国香港','日本','美国'],env.region)}</div><h3 class="settings-section">隐私与安全性</h3><div class="setting-row"><span class="setting-icon">▤</span><strong>向应用附加诊断信息<small>下次发送消息时附带这台电脑的地区和时区</small></strong><input id="virtualDiagnostics" type="checkbox" aria-label="附加诊断信息" ${env.shareDiagnostics?'checked':''}></div><div class="setting-row"><span class="setting-icon">▣</span><strong>登录设备<small>${env.sessions.length} 台设备 · 最近活动与连接位置</small></strong><button class="neutral" data-action="sessions">管理设备</button></div>`}
function changeVirtualNetwork(value){if(value===state.network)return;const previous=state.network;state.network=value;const env=state.environment,now=Date.now();env.transitions=env.transitions.filter(x=>now-x.at<90000);env.transitions.push({from:previous,to:value,at:now});env.sessions[0].place=value;recordActivity('网络从 '+previous+' 切换到 '+value);if(env.transitions.length>=3){securityEvent('短时间内连续切换网络出口',34);addMail('新登录提醒：你的账号刚刚环游了世界','刚刚检测到同一设备在不同连接位置重复登录。\n\n如果并非本人操作，请检查登录设备并撤销陌生会话。','Account Security')}log('Network connection changed: '+value);persist();renderApp('settings');notify('网络和 Internet','已连接',value)}
function inspectEnvironment(){const env=state.environment;const once=(key,reason,points)=>{if(env.seen.includes(key))return;env.seen.push(key);securityEvent(reason,points)};if(state.network==='上海直连')once('direct','当前连接位置出现地区使用情境线索',32);if(env.shareDiagnostics){recordActivity('发送了虚拟电脑诊断信息：'+env.region+' / '+env.timezone);if(env.region==='中国大陆')once('diagnostics','应用收到虚拟诊断中的地区使用情境线索',22);const mismatch=(/东京/.test(state.network)&&env.timezone!=='UTC+09:00')||(/洛杉矶/.test(state.network)&&env.timezone!=='UTC−08:00');if(mismatch)once('mismatch','诊断时区与当前连接位置不一致',12)}if(env.sessions.filter(x=>x.shared).length>=2)once('concurrent','多个陌生设备正在同时使用同一会话',36)}
function backgroundActivity(){if(state.restricted||!state.loggedIn)return;const env=state.environment;if(Date.now()-env.lastBackground<18000)return;env.lastBackground=Date.now();if(state.connections.shared){const entries=[{device:'OFFICE-LAPTOP',place:'洛杉矶出口',shared:true},{device:'Unknown Linux',place:'东京出口',shared:true},{device:'Cloud Worker 07',place:'其他连接位置',shared:true}];const next=entries.find(x=>!env.sessions.some(y=>y.device===x.device));if(next){env.sessions.push(next);securityEvent('共享会话新增设备：'+next.device,18);addMail('新的设备已登录','设备：'+next.device+'\n连接位置：'+next.place+'\n\n你本人还在这台电脑前，但另一台设备已经开始工作。可在设置中结束该会话。','Account Security')}}if(state.connections.extension){securityEvent('Batch Assistant 在后台新增 128 个排队任务',22);log('Batch Assistant: 128 background jobs queued.');notify('Batch Assistant','工作从未如此高效','128 个任务正在排队。你似乎没有点过开始。')}persist();refreshOthers()}
function sessionsDialog(){showDialog(`<div class="dialog-heading">登录设备<button data-action="closeDialog">×</button></div><p class="tiny">最近的账号会话</p>${state.environment.sessions.map((x,i)=>`<div class="session-card"><strong>${esc(x.device)}</strong><span>${esc(x.place)} · ${i===0?'当前设备':'刚刚活跃'}</span>${i?`<button class="neutral" data-end-session="${i}">结束会话</button>`:''}</div>`).join('')}<p class="tiny">如不认识其中的设备，请结束会话，并撤销向其提供访问权限的应用。</p>`)}
function reviewReport(){if(!state.reviewSnapshot&&!state.restricted)return;const snap=state.reviewSnapshot||{events:[],plan:state.plan,elapsed:Date.now()-state.started};const comedy=snap.events.some(x=>x.kind==='comedy');const signals=snap.events.filter(x=>x.kind==='signal');const title=signals.some(x=>/Batch|批量|第三方/.test(x.text))?'一键高效，一键下线':signals.some(x=>/共享|陌生|设备/.test(x.text))?'你买的是一个账号，大家用成了一间网吧':signals.some(x=>/网络/.test(x.text))?'人还在椅子上，账号已经环球旅行':'上一秒还在聊天';showDialog(`<div class="dialog-heading">本次事件复盘<button data-action="closeDialog">×</button></div><div class="review-hero"><span>ACCESS DISABLED</span><h2>${esc(title)}</h2><p>使用 ${Math.max(1,Math.floor(snap.elapsed/60000))} 分钟 · ${esc(snap.plan)} 计划 · ${signals.length} 项剧情信号</p></div><p>以下是本局虚拟电脑的事件记录。它解释本局如何触发剧情，并不是平台提供的真实封禁原因。</p><div class="review-timeline">${snap.events.length?snap.events.map(x=>`<div class="review-event ${esc(x.kind)}"><time>${esc(x.time)}</time><span>${esc(x.text)}</span><small>${x.kind==='signal'?'剧情信号':x.kind==='repair'?'处置操作':'操作记录'}</small></div>`).join(''):'未记录到完整事件。'}</div><h3>哪些值得带走</h3><div class="review-note"><strong>有公开依据</strong><p>服务有支持地区与使用政策；账号停用可以通过官方渠道申诉。Anthropic 说明会用 IP 等信号推断粗略地区。具体判定条件并未公开。</p><a href="https://privacy.anthropic.com/en/articles/11186740-does-claude-use-my-location" target="_blank" rel="noopener noreferrer">位置使用说明 ↗</a> · <a href="https://support.claude.com/en/articles/8241253-safeguards-warnings-and-appeals" target="_blank" rel="noopener noreferrer">停用与申诉 ↗</a></div><div class="review-note"><strong>本局的夸张演绎</strong><p>${comedy?'本局出现的“你是中国人吧？”等盘问和突然停用，是随机抽取的荒诞喜剧桥段，与真实国籍、设备或平台审核无关。 ':''}时间被压缩，网络、诊断信息和聊天情境的权重均由剧情设置。中文、国籍、系统时区都不能据此认定为真实封号原因。改语言或时区不能保证账号安全，也不改变服务的地区要求。</p></div><div class="review-note"><strong>现在可以做什么</strong><p>结束陌生会话，撤销不可信应用的权限，停止无人值守的批量操作；保存重要成果，保留通知并通过官方渠道核实。额度耗尽、网络故障与账号停用是不同问题。</p></div><div class="btn-row"><button class="primary" data-open="settings">检查设备与权限</button><button class="neutral" data-action="export">保存聊天</button><button class="neutral" data-action="closeDialog">返回桌面</button></div>`)}
Object.assign(actions,{sessions:sessionsDialog,reviewReport});
document.addEventListener('click',e=>{const b=e.target.closest('[data-end-session]');if(!b)return;const i=Number(b.dataset.endSession);if(i<=0||!state.environment.sessions[i])return;recordActivity('结束陌生设备会话：'+state.environment.sessions[i].device,'repair');state.environment.sessions.splice(i,1);state.risk=Math.max(0,state.risk-12);persist();sessionsDialog();if(windows.has('settings'))renderApp('settings')});
