function cancelComedy(){clearTimeout(comedyTimer);comedyTimer=null;comedyBusy=false;comedyCurrent=null;comedyLast=Date.now();comedyCooldown=50000+Math.floor(Math.random()*35000)}
function comedyContext(){const recent=activeChat().messages.filter(m=>m.role==='user').slice(-3).map(m=>m.text).join(' ');return {locale:state.localeClues.length>0||/中国|国内|上海|北京/.test(recent),thanks:/谢谢|好的|感谢/.test(recent),backup:!state.exported,network:state.environment.transitions.length>0}}
function pickComedy(source='claude'){const context=comedyContext(),recent=state.comedyRecent||[],pool=COMEDY_SCENES.map((scene,index)=>({scene,index,weight:scene.weight*(scene.context&&context[scene.context]?2.5:1)*(scene.source===source?4:1)})).filter(x=>!recent.includes(x.index));let n=Math.random()*pool.reduce((sum,x)=>sum+x.weight,0);for(const x of pool){n-=x.weight;if(n<=0)return x.index}return pool.at(-1).index}
function playComedy(index,source='claude'){if(state.restricted||!state.loggedIn||comedyBusy||$('osDialog').open)return false;clearTimeout(comedyTimer);comedyTimer=null;comedyBusy=true;comedyLast=Date.now();const pick=Number.isInteger(index)?Math.abs(index)%COMEDY_SCENES.length:pickComedy(source),scene=COMEDY_SCENES[pick],epoch=sessionEpoch;lastComedy=pick;comedySource=source;state.comedyRecent=[...(state.comedyRecent||[]),pick].slice(-3);comedyCurrent={scene,responded:false,choice:0};
 if(scene.source==='mail')addMail('Account review update','Hello,\n\nA review of recent account activity is in progress. No action is required at this time. If there is a change to your account status, we will contact you by email.\n\nAccount Support','Claude Account Support');recordActivity('随机剧情：'+scene.line+'（虚构演绎）','comedy');persist();
 showDialog(`<div class="comedy-scene" role="alert"><div class="comedy-header"><span class="comedy-brand">✳ Claude</span><span class="comedy-tag">ACCOUNT CHECK</span></div><div class="comedy-emblem">✳</div><h2>${esc(scene.line)}</h2><p>${esc(scene.detail)}</p><div class="comedy-choices"><button class="primary" data-action="comedyRetort">${esc(scene.reply)}</button><button class="neutral" data-action="comedyAside">${esc(scene.aside)}</button></div><div class="comedy-status"><span></span>请稍候，我们正在检查。</div></div>`);
 comedyTimer=setTimeout(()=>{if(epoch!==sessionEpoch||!comedyBusy||state.restricted)return;const status=document.querySelector('.comedy-status');if(status)status.textContent=scene.end;comedyTimer=setTimeout(()=>{if(epoch!==sessionEpoch||!comedyBusy||state.restricted)return;const chance=scene.ban===0?0:Math.min(.95,scene.ban+(state.risk>45?.12:0)-(comedyCurrent?.choice===1?.07:0));if(Math.random()<chance){recordActivity('随机剧情结果：账号停用（虚构）','comedy');restrictAccount()}else{recordActivity('随机剧情结果：虚惊一场，继续使用','comedy');cancelComedy();persist();closeDialog();notify('Claude','检查已完成',scene.safe);if(windows.has('claude'))focusWindow('claude')}},900+Math.floor(Math.random()*1200))},3000+Math.floor(Math.random()*2500));return true}
function maybeComedy(source='claude'){if(state.restricted||!state.loggedIn||comedyBusy||comedyTimer||Date.now()-comedyLast<comedyCooldown||Math.random()>=.22)return false;const epoch=sessionEpoch;comedyTimer=setTimeout(()=>{comedyTimer=null;if(epoch!==sessionEpoch||state.restricted)return;playComedy(undefined,source)},10000+Math.floor(Math.random()*18000));return true}
function ambientComedy(){if(state.restricted||!state.loggedIn||state.sent<1&&!(state.desktopOps>0)||comedyBusy||comedyTimer||Date.now()-comedyLast<Math.max(55000,comedyCooldown))return;if(Math.random()<.18)playComedy(undefined,comedySource);else comedyLast=Date.now()}
function respondComedy(choice){if(!comedyBusy||!comedyCurrent||comedyCurrent.responded)return;comedyCurrent.responded=true;comedyCurrent.choice=choice;recordActivity('剧情回应：'+(choice?comedyCurrent.scene.aside:comedyCurrent.scene.reply),'comedy');persist();document.querySelectorAll('.comedy-choices button').forEach(b=>b.disabled=true);const status=document.querySelector('.comedy-status');if(status)status.textContent=['你的说明已收到。请稍候。','我们理解你的意思。请稍候。','正在重新核对。请稍候。'][Math.floor(Math.random()*3)]}
Object.assign(actions,{comedyRetort:()=>respondComedy(0),comedyAside:()=>respondComedy(1)});
setInterval(ambientComedy,15000);

function newLocalAccount(){const previous=state,archive=previous.chats.map(c=>'# '+c.title+'\n\n'+c.messages.map(m=>(m.role==='user'?'你：':'助手：')+m.text).join('\n\n')).join('\n\n---\n\n');sessionEpoch++;generationId++;ChatEngine.cancel();cancelComedy();state=fresh();state.files=previous.files.map(f=>({...f}));state.notes=previous.notes;state.outbox=previous.outbox||[];state.mailDraft=previous.mailDraft||null;if(archive.trim())state.files.unshift({name:'上个账号的本地会话-'+Date.now()+'.txt',content:archive,time:stamp()});recordActivity('切换到新账号，本地文档与旧会话存档已保留','repair');typing=false;accountMenu=false;attached=false;mailIndex=0;reviewPending=false;closeDialog();persist();renderNotifications();for(const id of windows.keys())renderApp(id);openApp('claude');notify('Windows','本地文件已保留','新的账号会话已准备就绪。')}
Object.assign(actions,{newLocalAccount});

let lastDesktopActionAt=0;
function onDesktopAction(id){if(Date.now()-lastDesktopActionAt<6000)return;lastDesktopActionAt=Date.now();state.desktopOps=(state.desktopOps||0)+1;comedySource=id;recordActivity('打开'+(appList.find(x=>x[0]===id)?.[3]||id));persist();maybeComedy(id)}
function composeLocalMail(){const d=state.mailDraft||{};showDialog(`<div class="dialog-heading">新邮件<button data-action="closeDialog">×</button></div><form class="local-mail-form" id="localMailForm"><label>收件人<select id="draftRecipient"><option value="self">Player · 自己</option><option value="support" ${d.to==='support'?'selected':''}>Account Support</option></select></label><label>主题<input id="draftSubject" maxlength="100" value="${esc(d.subject||'')}" placeholder="添加主题"></label><label>正文<textarea id="draftBody" rows="7" placeholder="写点什么…">${esc(d.body||'')}</textarea></label><div class="btn-row"><button type="button" class="neutral" data-action="saveMailDraft">保存草稿</button><button class="primary" type="submit">放入本地发件箱</button></div><p class="tiny">此桌面的邮件在本地保存。</p></form>`)}
function readMailDraft(){return {to:$('draftRecipient')?.value||'self',subject:$('draftSubject')?.value||'',body:$('draftBody')?.value||''}}
function saveMailDraft(){state.mailDraft=readMailDraft();persist();closeDialog();notify('Outlook','草稿已保存','稍后可以继续编辑。')}
function localOutbox(){const list=state.outbox||[];showDialog(`<div class="dialog-heading">本地发件箱<button data-action="closeDialog">×</button></div>${list.length?list.map(x=>`<article class="outbox-card"><small>${esc(x.time)} · ${x.to==='self'?'Player':'Account Support'}</small><h3>${esc(x.subject||'（无主题）')}</h3><p>${esc(x.body).replace(/\n/g,'<br>')}</p></article>`).join(''):'<p class="tiny">这里还没有邮件。</p>'}`)}
function quickNetwork(){const net=state.network;showDialog(`<div class="dialog-heading">快速设置<button data-action="closeDialog">×</button></div><div class="quick-summary"><span>⌁</span><div><strong>${esc(net)}</strong><small>虚拟以太网连接 · PLAYER-PC</small></div></div><div class="quick-network-grid">${['自动连接','工作网络','公共网络','香港出口','东京出口','洛杉矶出口','上海直连'].map(n=>`<button class="network-tile ${net===n?'selected':''}" data-connect-network="${esc(n)}"><span>⌁</span>${esc(n)}<small>${net===n?'已连接':'连接'}</small></button>`).join('')}</div><div class="btn-row"><button class="neutral" data-open="settings">更多网络设置</button><button class="neutral" data-action="sessions">登录设备</button></div>`)}
function previewLocalFile(i){const f=state.files[i];if(!f)return;showDialog(`<div class="dialog-heading">${esc(f.name)}<button data-action="closeDialog">×</button></div><div class="file-preview-meta">文本文档 · ${f.content.length} 字符 · ${esc(f.time)}</div><pre class="file-preview">${esc(f.content)}</pre><div class="btn-row"><button class="primary" data-file="${i}">在记事本中编辑</button><button class="neutral" data-download="${i}">保存到本机</button></div>`)}
Object.assign(actions,{compose:composeLocalMail,saveMailDraft,localOutbox,quickNetwork});
document.addEventListener('input',e=>{if(e.target.id==='fileSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-filename]').forEach(row=>row.style.display=row.dataset.filename.includes(q)?'':'none')}if(['draftSubject','draftBody','draftRecipient'].includes(e.target.id)){state.mailDraft=readMailDraft();persist()}});
document.addEventListener('submit',e=>{if(e.target.id!=='localMailForm')return;e.preventDefault();const d=readMailDraft();state.outbox=state.outbox||[];state.outbox.unshift({...d,time:stamp()});state.mailDraft=null;recordActivity('写了一封本地邮件');persist();closeDialog();notify('Outlook','邮件已保存','已放入本地发件箱。');maybeComedy('mail')});
document.addEventListener('click',e=>{const n=e.target.closest('[data-connect-network]');if(n){changeVirtualNetwork(n.dataset.connectNetwork);closeDialog();maybeComedy('settings');return}const f=e.target.closest('[data-preview]');if(f)previewLocalFile(Number(f.dataset.preview))});
desktopReady=true;
